// === Tab: mySketch ===
//Pierre MARZIN 01/2019
//I'm using p5js Sound library to load and analyse 
//a song. Then, I pass the results of the analysis, as a texture, to the fragment shader.
//This shader will transform these informations in a 3d "landscape",
//using distance functions, and a rotating camera...
var button, song, amplitude, fft;
var waiting=true;
var img;
var program;
var texture,gl;
function preload() {
  song = loadSound('https://openprocessing.org/sketch/666100/files/alina.ogg');
}
function setup() {
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight,WEBGL);
	//img is the image where the spectrum data will be stored
	img=createImage(256,1);
	img.loadPixels();
  rectMode(CENTER);
	//shader is loaded with vert and frag definitions
  program = createShader(vert, frag);
	//cf Sound library doc
  amplitude = new p5.Amplitude();
  fft = new p5.FFT();
	//Since Chrome wont allow the creation of an audio context unless user use a gesture
	//this "fake" button asks you to click or touch the screen.This will trigger sound playing...
  var button=createButton('click or touch me!');
	button.position(.4*width,.25*width);
	button.style('font-size', '32px');
	button.size(.2*width,.1*height);
}
function draw() {  
	//Once you clicked or touch
  if (!waiting) {    
		//level reflects sound amplitude
    var level=.2+pow(amplitude.getLevel(),.6);
    var spectrum = fft.analyze();
		//spectrum is an array, containing the levels of each frequency
		//I convert it into a P5 Image, so to pass it to the shader as a texture
		for (var i = 0; i<4*256; i+=4) {
			var s=spectrum[i/4];
      img.pixels[i]=s;
      img.pixels[i+1]=s;
      img.pixels[i+2]=s;
      img.pixels[i+3]=s;
    }
		img.updatePixels();
		this.shader(program);
		//shaders uniforms are fed with our data
    program.setUniform('volume', level);
		program.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
    program.setUniform('iResolution', [width, height]);
    program.setUniform('iTime', millis()/1000);
    program.setUniform('iChannel0',img);
		//the scene is rendered as a rectangle
    rect(0, 0, width, height);
  }
}
function mousePressed() {
	//if the sound file is loaded...
  if (song.isLoaded()) {
    if (waiting) {
      song.play();	
      waiting=false;
			removeElements();
    }
  } 
	//if not send an alert message
	else alert('Sound file is loading...');
}

// === Tab: shader ===
var frag=`
// adapted from a Shader Created by inigo quilez - iq/2013
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
#ifdef GL_ES
  precision highp float;
#endif

uniform float iTime;
uniform float volume;
uniform vec2 iMouse;
uniform vec2 iResolution;
uniform sampler2D iChannel0;
varying highp vec2 vVertTexCoord;
vec3 hash3( float n )
{
    return fract(sin(vec3(n,n+1.0,n+2.0))*vec3(43758.5453123,22578.1459123,19642.3490423));
}

vec3 snoise3( in float x )
{
    float p = floor(x);
    float f = fract(x);
    f = f*f*(3.0-2.0*f);
    return -1.0 + 2.0*mix( hash3(p+0.0), hash3(p+1.0), f );
}

float freqs[16];

vec3 distanceLines( in vec3 ro, in vec3 rd, vec3 pa, vec3 pb )
{
	vec3 ba = pb - pa;
	vec3 oa = ro - pa;	
	float oad  = dot( oa, rd );
	float dba  = dot( rd, ba );
	float baba = dot( ba, ba );
	float oaba = dot( oa, ba );
	vec2 th = vec2( -oad*baba + dba*oaba, oaba - oad*dba ) / (baba - dba*dba);
	th.x = max(   th.x, 0.0 );
	th.y = clamp( th.y, 0.0, 1.0 );
	vec3 p = pa + ba*th.y;
	vec3 q = ro + rd*th.x;
	float l=1.4*length( p-q );
	return vec3(min(l*4.0*dot(q,p),l), th );
}

vec3 castRay( vec3 ro, vec3 rd, float linesSpeed )
{
	vec3 col = vec3(0.0);
	float mindist = 10000.0;
	vec3 p = vec3(0.2);
	float h = 0.0;
	float rad = 0.04 + 0.15*freqs[0];
	float mint = 0.0;
    for( int i=0; i<64; i++ )//noprotect
	{
		vec3 op = p;
		p  = 1.25*1.0*normalize(snoise3( 64.0*h + linesSpeed*0.015*iTime ));
		vec3 dis = distanceLines( ro, rd, op, p );
		vec3 lcol = 0.6 + 0.4*sin( 10.0*6.2831*h + vec3(0.0,0.6,0.9) );
		float m =pow( texture2D( iChannel0, vec2(h*0.5,0.5) ).x, 2.0 )*(1.0+2.0*h);
		float f = 1.0 - 4.0*dis.z*(1.0-dis.z);
		float width = 1240.0 - 1000.0*f;
		width *= 0.25;
		float ff = 1.0*exp(-0.06*dis.y*dis.y*dis.y);
		ff *= m;
		col += 0.3*lcol*exp( -0.3*width*dis.x*dis.x )*ff;
		col += 0.5*lcol*exp( -8.0*width*dis.x*dis.x )*ff;
		h += 1.0/128.0;
	}
    return col;
}
void main()
{
	vec2 q = gl_FragCoord.xy/iResolution.xy;
    vec2 p = -1.0+2.0*q;
	p.x *= iResolution.x/iResolution.y;
    vec2 mo = iMouse.xy/iResolution.xy;		 
	float time = iTime;
	for( int i=0; i<16; i++ )
	    freqs[i] =clamp( 1.9*pow( texture2D( iChannel0, vec2( 0.05 + 0.5*float(i)/16.0, 0.25 ) ).x, 3.0 ), 0.0, 1.0 );

	// camera	
	vec3 ta = vec3( 0.0, 0.0, 0.0 );	
  float camSpeed =.5*volume;	
	ta  = 0.2*vec3( cos(0.1*time), 0.0*sin(0.1*time), sin(0.07*time) );
	vec3 ro = vec3(2.0*cos(camSpeed*0.5*time+6.28*mo.x), 0.0, 2.0*sin(camSpeed*0.5*time+6.2831*mo.x) );
	float roll = 0.25*sin(camSpeed*time);

	// camera tx
	vec3 cw = normalize( ta-ro );
	vec3 cp = vec3( sin(roll), cos(roll),0.0 );
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv = normalize( cross(cu,cw) );
	vec3 rd = normalize( p.x*cu + p.y*cv + 1.2*cw );
	float curve  = smoothstep( 61.8, 71.0, iTime );
	curve -= smoothstep(103.0,113.0, iTime );
  rd.xy += curve*0.025*vec2( sin(34.0*q.y), cos(34.0*q.x) );
	rd = normalize(rd);		
	ro *= 1.0 -.5*freqs[1];
  vec3 col = castRay( ro, rd, 12.0 );
  col = col*col*2.4;

	// fade to black
    col *= 1.0 - smoothstep(188.0,228.00, iTime );
    col *=       smoothstep(  0.0,  4.00, iTime );
	if( iTime>61.8 && iTime<65.0 )
	col *= vec3(1.0)*clamp( (iTime-61.8)/(65.0-61.8), 0.0, 1.0 );
  col *= 0.15+0.85*pow( 16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.15 );
  gl_FragColor=vec4( col, 1.0 );
}
`;
var vert=`
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;
varying highp vec2 vVertTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vVertexNormal = normalize(vec3( uNormalMatrix * aNormal ));
  vVertTexCoord = aTexCoord;
}
`;

